// SAFE DEMO ONLY: no real phone numbers, Meta credentials or outbound sends.
const examples = [
  { id: 'wamid.WDFOX.TEST.SK.001', text: 'Dobrý deň, potrebujem cenovú ponuku na web stránku.' },
  { id: 'wamid.WDFOX.TEST.DE.002', text: 'Guten Tag, ich brauche ein Angebot für eine Website.' },
  { id: 'wamid.WDFOX.TEST.EN.003', text: 'Hi, I need a quote for my website.' },
  { id: 'wamid.WDFOX.TEST.SK.001', text: 'Dobrý deň, potrebujem cenovú ponuku na web stránku.' }, // test duplicate
];
return examples.map((e) => ({ json: {
  body: { object: 'whatsapp_business_account', entry: [{
    id: 'WABA_TEST_ONLY', changes: [{
      field: 'messages',
      value: { messaging_product: 'whatsapp',
        metadata: { display_phone_number: 'TEST', phone_number_id: 'PHONE_ID_TEST_ONLY' },
        messages: [{ from: 'SENDER_TEST_ONLY', id: e.id, timestamp: '1700000000', type: 'text', text: { body: e.text } }]
      }
    }]
  }] }
}}));

// Extract only message fields used by WDFOX; reject non-text and status-only events.
const output = [];
for (const input of $input.all()) {
  const body = input.json.body ?? input.json;
  const entries = Array.isArray(body.entry) ? body.entry : [];
  for (const entry of entries) {
    for (const change of (entry.changes ?? [])) {
      const value = change.value ?? {};
      for (const message of (value.messages ?? [])) {
        if (message.type !== 'text' || typeof message.text?.body !== 'string') continue;
        const text = message.text.body.trim();
        const messageId = String(message.id ?? '');
        if (!messageId || !text || text.length > 4000) continue;
        output.push({ json: {
          source: 'whatsapp_mock', tenant_id: 'WDFOX-TEST-ONLY',
          message_id: messageId, phone_number_id: String(value.metadata?.phone_number_id ?? ''),
          sender: 'SENDER_REDACTED', text,
          transport: 'dry-run', received_at: new Date().toISOString()
        } });
      }
    }
  }
}
return output;

// Deduplicate within this single execution ONLY. For production use persistent storage.
const seen = new Set();
return $input.all().map((item) => {
  const data = item.json;
  const duplicate = seen.has(data.message_id);
  if (!duplicate) seen.add(data.message_id);
  return { json: { ...data, duplicate, status: duplicate ? 'ignored_duplicate' : 'pending_review' } };
});

// Deterministic draft replies: no LLM, Meta API, CRM write or external call.
return $input.all().map((item) => {
  const msg = item.json;
  if (msg.duplicate) return { json: {
    message_id: msg.message_id, tenant_id: msg.tenant_id,
    status: 'ignored_duplicate', language: null, intent: null,
    reply_preview: null, approval_required: false,
    outbound_enabled: false, crm_write_enabled: false
  } };
  const t = msg.text.toLocaleLowerCase();
  const language = /[äöüß]|\b(guten|ich|brauche|für|angebot)\b/.test(t) ? 'de'
    : /[áäčďéíĺľňóôŕšťúýž]|\b(dobrý|potrebujem|ponuku|stránku)\b/.test(t) ? 'sk' : 'en';
  const intent = /cenov|ponuk|angebot|quote|estimate/.test(t) ? 'sales_quote' : 'customer_support';
  const replies = {
    sk: 'Dobrý deň! Ďakujeme za správu. Prosím, napíšte, akú webovú stránku potrebujete a aký je požadovaný termín. Radi pripravíme návrh.',
    de: 'Guten Tag! Vielen Dank für Ihre Nachricht. Bitte beschreiben Sie Ihre gewünschte Website und den Zeitrahmen. Wir erstellen gern einen Vorschlag.',
    en: 'Hello! Thanks for your message. Please tell us what kind of website you need and your timeline. We can prepare a proposal.'
  };
  return { json: {
    message_id: msg.message_id, tenant_id: msg.tenant_id,
    source: msg.source, detected_language: language, intent,
    original_text_demo: msg.text,
    reply_preview: replies[language],
    status: 'needs_human_approval', approval_required: true,
    outbound_enabled: false, crm_write_enabled: false,
    production_ready: false
  } };
});
